using System;

namespace TradeReconciliation.Domain
{
    /// <summary>
    /// A single row of <c>trades.csv</c>. Reference identity is intentional: duplicate rows with
    /// identical values are distinct pieces of evidence and must never collapse into one another.
    /// </summary>
    public sealed class TradeRecord
    {
        public string TradeId { get; init; } = string.Empty;
        public string Account { get; init; } = string.Empty;
        public string Instrument { get; init; } = string.Empty;
        public decimal Quantity { get; init; }
        public DateTime SettlementDate { get; init; }
        public string Currency { get; init; } = string.Empty;
        public decimal NetAmount { get; init; }
    }

    /// <summary>A single row of <c>positions.csv</c>.</summary>
    public sealed class PositionRecord
    {
        public string PositionId { get; init; } = string.Empty;
        public string Account { get; init; } = string.Empty;
        public string Instrument { get; init; } = string.Empty;
        public decimal Quantity { get; init; }
        public DateTime SettlementDate { get; init; }
        public string Currency { get; init; } = string.Empty;
    }

    /// <summary>A single row of <c>settlements.csv</c>.</summary>
    public sealed class SettlementRecord
    {
        public string SettlementId { get; init; } = string.Empty;
        public string Account { get; init; } = string.Empty;
        public string Instrument { get; init; } = string.Empty;
        public decimal Quantity { get; init; }
        public DateTime SettlementDate { get; init; }
        public string Currency { get; init; } = string.Empty;
        public decimal CashAmount { get; init; }
    }

    /// <summary>A single row of <c>overrides.csv</c>.</summary>
    public sealed class ManualOverrideRecord
    {
        public string TradeId { get; init; } = string.Empty;
        public string Action { get; init; } = string.Empty;
        public string Note { get; init; } = string.Empty;
        public string ApprovedBy { get; init; } = string.Empty;
    }
}

using System;

namespace TradeReconciliation.Domain
{
    /// <summary>A row of <c>matched-trades.csv</c>.</summary>
    public sealed class MatchedTradeRecord
    {
        public string TradeId { get; init; } = string.Empty;
        public string Status { get; init; } = string.Empty;
        public string Account { get; init; } = string.Empty;
        public string Instrument { get; init; } = string.Empty;
        public decimal Quantity { get; init; }
        public DateTime SettlementDate { get; init; }
        public string Currency { get; init; } = string.Empty;
        public string? PositionId { get; init; }
        public string? SettlementId { get; init; }
        public string? OverrideNote { get; init; }
    }

    /// <summary>A row of <c>break-queue.csv</c> plus the manual-override eligibility flag.</summary>
    public sealed class BreakRecord
    {
        public string TradeId { get; init; } = string.Empty;
        public string Account { get; init; } = string.Empty;
        public string Instrument { get; init; } = string.Empty;
        public decimal Quantity { get; init; }
        public DateTime SettlementDate { get; init; }
        public string Currency { get; init; } = string.Empty;
        public string Reasons { get; init; } = string.Empty;
        public string? PositionId { get; init; }
        public string? SettlementId { get; init; }

        /// <summary>
        /// True only when concrete position and settlement candidate sets exist for the trade.
        /// INV-3: an override can never manufacture a match without a concrete counterpart.
        /// </summary>
        public bool CanManualOverride { get; init; }
    }

    /// <summary>A row of <c>run-ledger.csv</c>.</summary>
    public sealed class RunLedgerEntry
    {
        public DateTime BusinessDate { get; init; }
        public string InputSignature { get; init; } = string.Empty;
        public int TotalTradesRead { get; init; }
        public int OpenBreakCount { get; init; }
        public int MatchedCount { get; init; }
    }

    /// <summary>Statuses written to the <c>status</c> column of <c>matched-trades.csv</c>.</summary>
    public static class MatchStatus
    {
        public const string Matched = "Matched";
        public const string ManualOverrideMatched = "ManualOverrideMatched";
        public const string ManualOverrideSuppressed = "ManualOverrideSuppressed";
    }

    /// <summary>Reason codes written to the <c>reasons</c> column of <c>break-queue.csv</c>.</summary>
    public static class BreakReason
    {
        public const string DuplicateTradeId = "DuplicateTradeId";
        public const string TradeValueOutOfBounds = "TradeValueOutOfBounds";
        public const string MissingPosition = "MissingPosition";
        public const string MissingSettlement = "MissingSettlement";
        public const string PositionSettlementDateMismatch = "PositionSettlementDateMismatch";
        public const string PositionCurrencyMismatch = "PositionCurrencyMismatch";
        public const string PositionQuantitySignMismatch = "PositionQuantitySignMismatch";
        public const string PositionQuantityOutOfTolerance = "PositionQuantityOutOfTolerance";
        public const string SettlementDateMismatch = "SettlementDateMismatch";
        public const string SettlementCurrencyMismatch = "SettlementCurrencyMismatch";
        public const string SettlementQuantitySignMismatch = "SettlementQuantitySignMismatch";
        public const string SettlementQuantityOutOfTolerance = "SettlementQuantityOutOfTolerance";
        public const string SettlementAmountOutOfTolerance = "SettlementAmountOutOfTolerance";
    }

    /// <summary>Manual override actions, compared after trimmed-uppercase normalization.</summary>
    public static class OverrideAction
    {
        public const string ForceMatch = "FORCEMATCH";
        public const string SuppressBreak = "SUPPRESSBREAK";
    }
}

using System.Collections.Generic;

namespace TradeReconciliation.Domain
{
    /// <summary>
    /// Immutable outcome of a reconciliation pass. All collections are already in the
    /// deterministic order used by the output files (REQ-5).
    /// </summary>
    public sealed class ReconciliationResult
    {
        public IReadOnlyList<MatchedTradeRecord> MatchedTrades { get; init; } = new List<MatchedTradeRecord>();
        public IReadOnlyList<BreakRecord> OpenBreaks { get; init; } = new List<BreakRecord>();
        public IReadOnlyList<ManualOverrideRecord> StaleOverrides { get; init; } = new List<ManualOverrideRecord>();
        public int TotalTradesRead { get; init; }
        public int CanonicalTradeCount { get; init; }
        public int DuplicateTradeCount { get; init; }
        public int MatchedCount { get; init; }
        public int ManualOverrideMatchedCount { get; init; }
        public int ManualOverrideSuppressedCount { get; init; }
    }
}

namespace TradeReconciliation.Configuration
{
    /// <summary>
    /// The externally observable file-name contract. These names are a compatibility boundary
    /// (REQ-5) and must not change without a downstream operations change.
    /// </summary>
    public static class BatchFileNames
    {
        public const string Trades = "trades.csv";
        public const string Positions = "positions.csv";
        public const string Settlements = "settlements.csv";
        public const string Overrides = "overrides.csv";

        public const string MatchedTrades = "matched-trades.csv";
        public const string BreakQueue = "break-queue.csv";
        public const string EndOfDayReport = "end-of-day-report.txt";
        public const string RunLedger = "run-ledger.csv";
    }
}

using System;
using System.Globalization;

namespace TradeReconciliation.Configuration
{
    /// <summary>
    /// Externally configurable matching tolerances. Defaults reproduce the legacy
    /// <c>BatchConfiguration</c> constants exactly; overriding them is opt-in.
    /// </summary>
    public sealed class ReconciliationOptions
    {
        public const string PositionQuantityToleranceVariable = "TRADERECON_POSITION_QUANTITY_TOLERANCE";
        public const string SettlementQuantityToleranceVariable = "TRADERECON_SETTLEMENT_QUANTITY_TOLERANCE";
        public const string SettlementAmountToleranceVariable = "TRADERECON_SETTLEMENT_AMOUNT_TOLERANCE";

