using System;
using System.Collections.Generic;
using System.Globalization;
using System.Linq;
using System.Reflection;

namespace TradeReconciliation.Tests.Framework
{
    /// <summary>
    /// Marks a public static parameterless method as an automated test. A tiny in-repo runner is
    /// used deliberately: the batch must build and test on a clean, offline machine with nothing
    /// but the .NET 8 SDK, so the test suite carries no external package dependencies (NFR-4).
    /// </summary>
    [AttributeUsage(AttributeTargets.Method, AllowMultiple = false, Inherited = false)]
    public sealed class TestCaseAttribute : Attribute
    {
        public TestCaseAttribute(string requirement)
        {
            Requirement = requirement;
        }

        /// <summary>Requirement, acceptance criterion, or invariant this test covers.</summary>
        public string Requirement { get; }
    }

    public static class TestRunner
    {
        public static int Run(Assembly assembly)
        {
            List<MethodInfo> tests = assembly.GetTypes()
                .SelectMany(type => type.GetMethods(BindingFlags.Public | BindingFlags.Static))
                .Where(method => method.GetCustomAttribute<TestCaseAttribute>() != null && method.GetParameters().Length == 0)
                .OrderBy(method => method.DeclaringType!.FullName, StringComparer.Ordinal)
                .ThenBy(method => method.Name, StringComparer.Ordinal)
                .ToList();

            if (tests.Count == 0)
            {
                Console.Error.WriteLine("No tests were discovered.");
                return 1;
            }

            var failures = new List<string>();

            foreach (MethodInfo test in tests)
            {
                string name = test.DeclaringType!.Name + "." + test.Name;
                string requirement = test.GetCustomAttribute<TestCaseAttribute>()!.Requirement;

                try
                {
                    test.Invoke(null, null);
                    Console.WriteLine("[PASS] " + name + " (" + requirement + ")");
                }
                catch (TargetInvocationException invocation)
                {
                    Exception actual = invocation.InnerException ?? invocation;
                    failures.Add(name);
                    Console.WriteLine("[FAIL] " + name + " (" + requirement + ")");
                    Console.WriteLine("       " + actual.Message.Replace(Environment.NewLine, Environment.NewLine + "       ", StringComparison.Ordinal));
                }
            }

            Console.WriteLine();
            Console.WriteLine(string.Format(
                CultureInfo.InvariantCulture,
                "{0} tests, {1} passed, {2} failed.",
                tests.Count,
                tests.Count - failures.Count,
                failures.Count));

            if (failures.Count > 0)
            {
                Console.WriteLine("Failed: " + string.Join(", ", failures));
                return 1;
            }

            return 0;
        }
    }

    /// <summary>Minimal assertion helpers with messages that pinpoint the mismatch.</summary>
    public static class Assert
    {
        public static void IsTrue(bool condition, string message)
        {
            if (!condition)
            {
                throw new AssertionException("Expected true: " + message);
            }
        }

        public static void IsFalse(bool condition, string message)
        {
            if (condition)
            {
                throw new AssertionException("Expected false: " + message);
            }
        }

        public static void AreEqual(string? expected, string? actual, string message)
        {
            if (!string.Equals(expected, actual, StringComparison.Ordinal))
            {
                throw new AssertionException(
                    message + Environment.NewLine +
                    "Expected:" + Environment.NewLine + expected + Environment.NewLine +
                    "Actual:" + Environment.NewLine + actual);
            }
        }

        public static void AreEqual(int expected, int actual, string message)
        {
            if (expected != actual)
            {
                throw new AssertionException(
                    message + " Expected " + expected.ToString(CultureInfo.InvariantCulture) +
                    " but found " + actual.ToString(CultureInfo.InvariantCulture) + ".");
            }
        }

        public static void AreEqual(decimal expected, decimal actual, string message)
        {
            if (expected != actual)
            {
                throw new AssertionException(
                    message + " Expected " + expected.ToString(CultureInfo.InvariantCulture) +
                    " but found " + actual.ToString(CultureInfo.InvariantCulture) + ".");
            }
        }

        public static void Contains(string haystack, string needle, string message)
        {
            if (haystack.IndexOf(needle, StringComparison.Ordinal) < 0)
            {
                throw new AssertionException(message + " Missing text: " + needle + Environment.NewLine + haystack);
            }
        }

        public static void DoesNotContain(string haystack, string needle, string message)
        {
            if (haystack.IndexOf(needle, StringComparison.Ordinal) >= 0)
            {
                throw new AssertionException(message + " Unexpected text: " + needle + Environment.NewLine + haystack);
            }
        }

        public static TException Throws<TException>(Action action, string message)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (TException expected)
            {
                return expected;
            }
            catch (Exception unexpected)
            {
                throw new AssertionException(
                    message + " Expected " + typeof(TException).Name + " but caught " + unexpected.GetType().Name + ": " + unexpected.Message);
            }

            throw new AssertionException(message + " Expected " + typeof(TException).Name + " but nothing was thrown.");
        }
    }

    public sealed class AssertionException : Exception
    {
        public AssertionException(string message)
            : base(message)
        {
        }
    }
}

